from pathlib import Path
import re,base64
root=Path.cwd(); template=Path('C:/Users/Данила/.codex/skills/frontend-design/assets/preview-template.html').read_text(encoding='utf-8')
def img(n):return 'data:image/png;base64,'+base64.b64encode((root/'public/assets/udav'/f'{n}.png').read_bytes()).decode()
ui='<div class="review-phone" data-fd-id="section-home"><img data-fd-id="art-header" src="'+img('header')+'" alt="УДАВ · 1 240 очков"/><img data-fd-id="art-snake" src="'+img('hero')+'" alt="Кто тут самый тряский?"/><img data-fd-id="row-sasha" src="'+img('nearby-row')+'" alt="Саша рядом"/><button data-fd-id="btn-challenge"><img src="'+img('battle-button')+'" alt="Вызвать на батл"/></button><button data-fd-id="btn-invite"><img style="width:60%;margin:auto" src="'+img('invite-button')+'" alt="Пригласить друга"/></button><nav data-fd-id="nav-main"><b data-fd-id="text-battles" data-fd-editable="text">Батлы</b><b data-fd-id="text-ranking" data-fd-editable="text">Рейтинг</b><b data-fd-id="text-profile" data-fd-editable="text">Профиль</b></nav></div>'
start=template.index('      <!-- LIGHT PREVIEW -->');end=template.index('    </section>',start)
panes=''
for theme,arrow in [('light','▶'),('dark','◀')]:panes+=f'<div class="preview theme-{theme}" id="preview-{theme}" data-theme="{theme}"><button class="pane-toggle-btn" data-pane="{theme}">{arrow}</button>'+ui+'</div>'
template=template[:start]+panes+'</div>'+template[end:]
template=re.sub(r'const PREVIEW_META = .*?\n};',"const PREVIEW_META = {source: '.frontend-design/udav/2026-11-05-udav.html',topic:'УДАВ — точный главный экран',targetFile:'src/prototype.css'};",template,count=1,flags=re.S)
template=re.sub(r'const TOKENS = .*?\n];',"""const TOKENS={brand:[{key:'--udav-lime',intent:'Активная вкладка',kind:'color',options:[{id:'Original',light:'#d6ff00',dark:'#d6ff00',note:'original default'},{id:'Soft',light:'#e1ff66',dark:'#e1ff66',note:'soft'}]}],touch:[{key:'--udav-radius',intent:'Скругление вкладок',kind:'slider',min:18,max:36,step:2,defaultValue:28,unit:'px'}]};
const SECTION_ORDER=[['Удав: акцент','brand'],['Удав: нажатия','touch']];""",template,count=1,flags=re.S)
css='''.preview{padding:24px!important;background:#ede9e2!important}.theme-dark{background:#252124!important}.review-phone{max-width:350px;margin:auto;background:#fffaf2;color:#15110e}.review-phone img{width:100%;display:block}.review-phone button{border:0;padding:0;background:transparent;display:block;width:100%;cursor:pointer}.review-phone nav{display:flex;justify-content:space-around;gap:8px;padding:18px 4px;font:14px Arial}.review-phone nav b:first-child{background:var(--udav-lime,#d6ff00);border-radius:var(--udav-radius,28px);padding:8px}.review-phone nav b{padding:8px}.review-phone button:active{transform:scale(.97)}'''
template=template.replace('</head>','<style>'+css+'</style></head>').replace('<title>frontend-design preview</title>','<title>УДАВ · Дизайн-ревью</title>').replace('frontend-design preview','УДАВ · Дизайн-ревью').replace('Project UI preview','УДАВ · Дизайн-ревью').replace('__topic__','УДАВ')
out=root/'.frontend-design/udav/2026-11-05-udav.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(template,encoding='utf-8');(root/'public/review.html').write_text(template,encoding='utf-8')
script=re.search(r'<script>(.*?)</script>',template,re.S).group(1);(root/'scripts/check-review.cjs').write_text(script,encoding='utf-8')
